import { ExecArgs } from "@medusajs/framework/types"
import { PAGE_LAYOUT_MODULE } from "../modules/page-layout"

/**
 * Seeds the default homepage layout (matches the current hardcoded sections in index.astro).
 *
 * Section format:
 * {
 *   id: string         // unique identifier (uuid-ish, generated by builder)
 *   type: string       // section type — must match a section schema
 *   visible: boolean   // toggle visibility without removing
 *   props: object      // props passed to the section component
 * }
 */
export default async function seedPageLayouts({ container }: ExecArgs) {
  const service = container.resolve(PAGE_LAYOUT_MODULE) as any

  console.log("Seeding default homepage layout...")

  // Default homepage sections — mirror current index.astro
  const homepageSections = [
    {
      id: "sec_hero",
      type: "hero",
      visible: true,
      props: {
        variant: "split-right",
        badge: "Livraison gratuite des 50€",
        title: "L'essentiel pour <span class=\"text-primary\">bébé</span> & <span class=\"text-secondary\">maman</span>",
        subtitle: "Des produits soigneusement selectionnes pour accompagner chaque etape de la maternite.",
        cta_primary: { text: "Decouvrir la boutique", url: "/collections" },
        cta_secondary: { text: "Lire nos conseils", url: "/blog" },
        image_url: "/images/hero/hero-mother-baby.webp",
      },
    },
    {
      id: "sec_categories",
      type: "collection_bubbles",
      visible: true,
      props: {
        title: "Nos univers",
        limit: 12,
      },
    },
    {
      id: "sec_featured_products",
      type: "featured_products",
      visible: true,
      props: {
        title: "Nos produits phares",
        subtitle: "Selectionnes avec soin pour vous",
        limit: 8,
        cta_text: "Tout voir",
        cta_url: "/collections",
      },
    },
    {
      id: "sec_trust_bar",
      type: "trust_bar",
      visible: true,
      props: {
        items: [
          { icon: "truck", title: "Livraison 24-48h", subtitle: "Gratuite des 50€" },
          { icon: "card", title: "Paiement securise", subtitle: "Stripe · 3D Secure" },
          { icon: "return", title: "Retour offert", subtitle: "30 jours satisfait" },
          { icon: "headset", title: "Conseil expert", subtitle: "Reponse sous 24h" },
        ],
      },
    },
    {
      id: "sec_marquee",
      type: "ticker_marquee",
      visible: true,
      props: {
        items: ["Livraison rapide", "Paiement securise", "Retours gratuits"],
      },
    },
    {
      id: "sec_features",
      type: "features",
      visible: true,
      props: {},
    },
    {
      id: "sec_stats",
      type: "stats_counter",
      visible: true,
      props: {},
    },
    {
      id: "sec_testimonials",
      type: "testimonials",
      visible: true,
      props: {
        title: "Ce que disent nos clientes",
        subtitle: "Plus de 1500 mamans nous font confiance",
      },
    },
    {
      id: "sec_blog_preview",
      type: "blog_preview",
      visible: true,
      props: {
        title: "Conseils & astuces",
        subtitle: "Des articles pour vous accompagner au quotidien",
        limit: 3,
      },
    },
    {
      id: "sec_newsletter",
      type: "newsletter",
      visible: true,
      props: {
        title: "Rejoignez la communaute Magic Crochet Kit",
        subtitle: "Recevez nos conseils et offres exclusives.",
      },
    },
  ]

  // Check if homepage layout already exists
  const existing = await service.listPageLayouts({ page_key: "homepage" }, { take: 10 })
  if (existing.length > 0) {
    console.log(`  Layout 'homepage' deja present (${existing.length} entree(s)). Skipping.`)
    return
  }

  // Create published version
  await service.createPageLayouts({
    page_key: "homepage",
    status: "published",
    sections: homepageSections,
    published_at: new Date(),
  })
  console.log(`  + homepage (published) — ${homepageSections.length} sections`)

  // Create draft (initially same as published)
  await service.createPageLayouts({
    page_key: "homepage",
    status: "draft",
    sections: homepageSections,
  })
  console.log(`  + homepage (draft) — ${homepageSections.length} sections`)

  console.log("Done!")
}
